import type { TBox } from "@/core/geometry"
import type { TPoint, TSegment } from "@/core/geometry"
import { BoxOps } from "@/core/geometry"
import { MatrixTransform, mergeSymbolTransform, OBBOps, type TOBB } from "@/core/geometry"
import { isValidPoint } from "@/core/geometry"
import type { TPartialDeep } from "@/core/std"
import { createUUID } from "@/core/std"
import type { TStyle } from "@/style"
import { mergeSymbolStyle } from "@/style"
import type { TBaseSymbol } from "@/symbol/Symbol"
import { SymbolType } from "@/symbol/Symbol"

import { ShapeKind } from "./Shape-enum"

/**
 * @group Symbol
 */
export type TShapePolygon = TBaseSymbol & {
  type: SymbolType.Shape
  kind: ShapeKind.Polygon
  style: TStyle
  points: TPoint[]
}

/**
 * @group Symbol
 */
export const ShapePolygonOps = {
  create(points: TPoint[], style?: TPartialDeep<TStyle>): TShapePolygon {
    const mergedStyle = mergeSymbolStyle(style)
    const now = Date.now()
    const polygon: TShapePolygon = {
      type: SymbolType.Shape,
      kind: ShapeKind.Polygon,
      id: `${SymbolType.Shape}-${createUUID()}`,
      style: mergedStyle,
      creationTime: now,
      modificationDate: now,
      points,
      transform: MatrixTransform.identity(),
    }
    return polygon
  },

  createFromPartial(partial: TPartialDeep<TShapePolygon>): TShapePolygon {
    if (!partial?.points || partial?.points?.length < 3) {
      throw new Error(`Unable to create polygon at least 3 points required`)
    }
    if (partial?.points?.some((p) => !isValidPoint(p))) {
      throw new Error(`Unable to create a polygon, one or more points are invalid`)
    }
    const polygon = ShapePolygonOps.create(partial.points as TPoint[], partial.style)
    if (partial.id) {
      polygon.id = partial.id
    }
    polygon.transform = mergeSymbolTransform(partial.transform)
    return polygon
  },

  /**
   * A polygon's vertices are the points it stores, returned as-is.
   *
   * Named rather than inlined so every caller goes through one place, like
   * `EdgePolyLineOps.computeVertices`.
   */
  computeVertices(polygon: TShapePolygon): TPoint[] {
    return polygon.points
  },

  /** Takes the points, like {@link computeEdges}: a polygon's box is the box of its own vertices. */
  computeBounds(points: TPoint[]): TOBB {
    return OBBOps.createFromPoints(points)
  },

  computeEdges(points: TPoint[]): TSegment[] {
    return points.map((p, i) => ({
      p1: p,
      p2: points[(i + 1) % points.length],
    }))
  },

  overlaps(polygon: TShapePolygon, box: TBox): boolean {
    return OBBOps.polygonOverlapsBox(
      ShapePolygonOps.computeBounds(polygon.points),
      ShapePolygonOps.computeEdges(polygon.points),
      box
    )
  },

  createTriangleBetweenPoints(origin: TPoint, target: TPoint, style?: TPartialDeep<TStyle>): TShapePolygon {
    const points: TPoint[] = [
      { x: origin.x, y: origin.y },
      { x: target.x, y: origin.y },
      {
        x: (origin.x + target.x) / 2,
        y: target.y,
      },
    ]
    return ShapePolygonOps.create(points, style)
  },

  updateTriangleBetweenPoints(poly: TShapePolygon, origin: TPoint, target: TPoint): void {
    poly.points = [
      { x: origin.x, y: origin.y },
      { x: target.x, y: origin.y },
      {
        x: (origin.x + target.x) / 2,
        y: target.y,
      },
    ]
    poly.modificationDate = Date.now()
  },

  createParallelogramBetweenPoints(origin: TPoint, target: TPoint, style?: TPartialDeep<TStyle>): TShapePolygon {
    const points: TPoint[] = [
      { x: origin.x, y: origin.y },
      {
        x: origin.x + (target.x - origin.x) * 0.75,
        y: origin.y,
      },
      { x: target.x, y: target.y },
      {
        x: origin.x + (target.x - origin.x) * 0.25,
        y: target.y,
      },
    ]
    return ShapePolygonOps.create(points, style)
  },

  updateParallelogramBetweenPoints(poly: TShapePolygon, origin: TPoint, target: TPoint): void {
    poly.points = [
      { x: origin.x, y: origin.y },
      {
        x: origin.x + (target.x - origin.x) * 0.75,
        y: origin.y,
      },
      { x: target.x, y: target.y },
      {
        x: origin.x + (target.x - origin.x) * 0.25,
        y: target.y,
      },
    ]
    poly.modificationDate = Date.now()
  },

  createRectangleBetweenPoints(origin: TPoint, target: TPoint, style?: TPartialDeep<TStyle>): TShapePolygon {
    const box = BoxOps.createFromPoints([origin, target])
    const points: TPoint[] = [
      { x: box.x, y: box.y },
      { x: box.x + box.width, y: box.y },
      {
        x: box.x + box.width,
        y: box.y + box.height,
      },
      { x: box.x, y: box.y + box.height },
    ]
    return ShapePolygonOps.create(points, style)
  },

  updateRectangleBetweenPoints(poly: TShapePolygon, origin: TPoint, target: TPoint): void {
    const box = BoxOps.createFromPoints([origin, target])
    poly.points = [
      { x: box.x, y: box.y },
      { x: box.x + box.width, y: box.y },
      {
        x: box.x + box.width,
        y: box.y + box.height,
      },
      { x: box.x, y: box.y + box.height },
    ]
    poly.modificationDate = Date.now()
  },

  createRhombusBetweenPoints(origin: TPoint, target: TPoint, style?: TPartialDeep<TStyle>): TShapePolygon {
    const box = BoxOps.createFromPoints([origin, target])
    const points: TPoint[] = [
      { x: box.x + box.width / 2, y: box.y },
      {
        x: box.x + box.width,
        y: box.y + box.height / 2,
      },
      {
        x: box.x + box.width / 2,
        y: box.y + box.height,
      },
      { x: box.x, y: box.y + box.height / 2 },
    ]
    return ShapePolygonOps.create(points, style)
  },

  updateRhombusBetweenPoints(poly: TShapePolygon, origin: TPoint, target: TPoint): void {
    const box = BoxOps.createFromPoints([origin, target])
    poly.points = [
      { x: box.x + box.width / 2, y: box.y },
      {
        x: box.x + box.width,
        y: box.y + box.height / 2,
      },
      {
        x: box.x + box.width / 2,
        y: box.y + box.height,
      },
      { x: box.x, y: box.y + box.height / 2 },
    ]
    poly.modificationDate = Date.now()
  },

  getSVGPath(polygon: TShapePolygon): string {
    let path = `M ${polygon.points[0].x} ${polygon.points[0].y}`
    for (let i = 1; i < polygon.points.length; i++) {
      path += ` L ${polygon.points[i].x} ${polygon.points[i].y}`
    }
    return path + " Z"
  },
}
